mapper.select:
SELECT /* 3) 어제까지 전체 개수 = (어제까지 제출) + (어제까지 예정) */ ( (SELECT COUNT(*) FROM inspections i WHERE TRUNC(i.submitted_at) < TRUNC(SYSDATE)) + (SELECT COUNT(*) FROM facilities f WHERE TRUNC(f.next_scheduled_at) < TRUNC(SYSDATE)) ) AS untilYesterdayTotal,
/* 3) 어제까지 완료 개수 = 어제까지 제출 */ (SELECT COUNT(*) FROM inspections i WHERE TRUNC(i.submitted_at) < TRUNC(SYSDATE)) AS untilYesterdayCompleted,
/* 4) 오늘 이후 예정 */ (SELECT COUNT(*) FROM facilities f WHERE TRUNC(f.next_scheduled_at) > TRUNC(SYSDATE)) AS upcomingCount,
/* 5) 미점검 현황 (어제까지인데 점검 레코드가 전혀 없는 설비 수) */ ( SELECT COUNT(*) FROM facilities f WHERE f.next_scheduled_at < TRUNC(SYSDATE) -- '어제까지' 포함 ) AS overdueUninspected FROM dual
